{
  "meta": {
    "name": "Free Premium App",
    "description": "A free application that offers exclusive features to premium subscribers who do not pay."
  },
  "entities": [
    {
      "name": "Subscriber",
      "ownable": false,
      "fields": [
        {
          "name": "userId",
          "type": "string",
          "required": true,
          "unique": true
        },
        {
          "name": "isPremium",
          "type": "boolean",
          "required": true,
          "default": false
        }
      ]
    },
    {
      "name": "Feature",
      "ownable": false,
      "fields": [
        {
          "name": "featureId",
          "type": "string",
          "required": true,
          "unique": true
        },
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "isPaidOnly",
          "type": "boolean",
          "required": true,
          "default": false
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "premiumSubscriber",
      "description": "User with access to exclusive features",
      "isDefault": false
    },
    {
      "name": "standardUser",
      "description": "Default user role",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "premiumSubscriber",
      "entity": "Feature",
      "actions": [
        "read"
      ],
      "scope": "all",
      "requiresPlan": "premium"
    },
    {
      "role": "standardUser",
      "entity": "Feature",
      "actions": [
        "read"
      ],
      "scope": "all",
      "requiresPlan": "free"
    }
  ],
  "pages": [
    {
      "name": "Features List",
      "route": "/features",
      "type": "list",
      "entity": "Feature",
      "access": [
        "premiumSubscriber",
        "standardUser"
      ]
    },
    {
      "name": "Premium Feature Access",
      "route": "/premium-feature",
      "type": "custom",
      "access": [
        "premiumSubscriber"
      ],
      "requiresPlan": "premium"
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "isDefault": true,
      "features": [
        "featureAccessControl"
      ]
    },
    {
      "name": "premium",
      "price": 0,
      "features": [
        "featureAccessControl"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumFeatureGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Premium Feature Access"
        ],
        "features": [
          "featureAccessControl"
        ]
      }
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
